// n8n Code node (JavaScript)
// Entrada: o item 0 contém o JSON exibido na sua mensagem (array com 1 objeto que tem "highlights").
// Saída: 1 item com um highlight escolhido aleatoriamente.

const payload = $input.first().json;

const root = Array.isArray(payload) ? payload[0] : payload;
const highlights = Array.isArray(root?.highlights) ? root.highlights : [];

if (highlights.length === 0) {
  throw new Error('Nenhum highlight encontrado no JSON de entrada.');
}

const idx = Math.floor(Math.random() * highlights.length);
const chosen = highlights[idx];

const meta = {};
['review_id', 'review_url', 'review_completed'].forEach(k => {
  if (root?.[k] !== undefined) meta[k] = root[k];
});

return [
  {
    json: {
      ...meta,
      pickedIndex: idx,
      total: highlights.length,
      ...chosen,
    },
  },
];

const raw = $input.first().json;

// Com Output Format = JSON Schema, o nó OpenAI já devolve o objeto parseado.
// Mantém compatibilidade caso volte como string.
const content = raw?.output?.[0]?.content?.[0]?.text;

if (content === undefined || content === null || content === '') {
  throw new Error('Não foi encontrado conteúdo em output[0].content[0].text');
}

let parsed = content;
if (typeof content === 'string') {
  try {
    parsed = JSON.parse(content);
  } catch (error) {
    throw new Error('O conteúdo retornado pela OpenAI não é um JSON válido.');
  }
}

// Autor vem direto do highlight original, nunca do modelo de tradução
// (evita que o LLM devolva texto de instrução em vez do valor real).
const originalAuthor = $('Extrai somente 1 highlight').first().json.author || '';

return [
  {
    json: {
      title: parsed.title || '',
      text: parsed.text || '',
      author: originalAuthor
    }
  }
];
